    const RANDOM_SHIFTS = ['LinearShift', 'LinearShift', 'ThingusShift', 'ZoomShift', 'RingSpinShift', 'StretchShift', 'TileShift', 'TrigShift', 'SinShimmerShift', 'EdgeFalloffShift', 'StarburstShift', 'SwirlShift', 'TrigStretchShift', 'Twirlocity', 'Shiitake'];

    // a shift table built a few rows at a time (Setup: 3 rows a frame) or all at once (Complete)
    function shiftTable(name, params) {
        const S = (typeof name === 'object' && name) || SHIFTS[name] || SHIFTS.StretchShift;
        const p = Float64Array.from({ length: 8 }, (_, i) => +(params && params[i]) || 0);
        const t = { name, S, p, flags: S.flags || 0, table: new Int32Array(BW * BH), row: 0 };
        t.build = (rows) => {
            const W = BW; const H = BH;
            for (let n = 0; n < rows && t.row < H; n++, t.row++) {
                const y = t.row;
                for (let x = 0; x < W; x++) {
                    let [sx, sy] = S.form(x, y, p, W, H);
                    if (!(sx >= 0 && sx < W)) sx = S.wrap ? x : 0;
                    if (!(sy >= 0 && sy < H)) sy = S.wrap ? y : 0;
                    t.table[y * W + x] = sy * W + sx;
                }
            }
            return t.row >= H;
        };
        return t;
    }

    // ---- draws (CRenderEffect subclasses), one instance each per page, flags 1 = edge draws ----

    function drawLine(buf, x0, y0, x1, y1, c) {
        const W = rd.W; const N = W * rd.H;
        let p = y0 * W + x0; let sy = W; let dy = y1 - y0;
        if (dy < 0) { dy = -dy; sy = -W; }
        let dx = x1 - x0; let sx = 1;
        if (dx < 0) { dx = -dx; sx = -1; }
        let err = 0;
        if (dx > dy) {
            for (let i = 0; i <= dx; i++) { if (p >= 0 && p < N) buf[p] = c; p += sx; err += dy; if (err > dx) { err -= dx; p += sy; } }
        } else {
            for (let i = 0; i <= dy; i++) { if (p >= 0 && p < N) buf[p] = c; p += sy; err += dx; if (err > dy) { err -= dy; p += sx; } }
        }
    }
